const absoluteSchemePattern = /^[a-zA-Z][a-zA-Z\d+.-]*:/;
const filesystemRootPattern = /^\/(?:home|Users|private|var|tmp|mnt|opt|etc)(?:\/|$)|^\/[a-zA-Z]:\//;
export const isExternalUrl = (href) => {
    if (!href)
        return false;
    return absoluteSchemePattern.test(href) || href.startsWith("//");
};
export const resolveBaseUrl = (path = "", baseUrl = "/") => {
    if (isExternalUrl(path)) {
        return path;
    }
    if (path.startsWith("#") || path.startsWith("?")) {
        return path;
    }
    const cleanPath = path.startsWith("/") ? path.slice(1) : path;
    const normalizedBase = baseUrl.endsWith("/") ? baseUrl : `${baseUrl}/`;
    return `${normalizedBase}${cleanPath}`;
};
function readEnvBaseUrl() {
    try {
        return import.meta.env.BASE_URL ?? "/";
    }
    catch {
        return "/";
    }
}
export function url(path = "", baseOverride) {
    const baseUrl = baseOverride ?? readEnvBaseUrl();
    return resolveBaseUrl(path, baseUrl);
}
/**
 * Returns true when a value is a site-internal root-relative path that should
 * be rewritten to include the current Astro base path. Hashes, queries,
 * external/scheme-prefixed URLs, and likely filesystem paths return false.
 */
export function isBaseRelativePath(value) {
    if (!value)
        return false;
    if (isExternalUrl(value))
        return false;
    if (value.startsWith("#") || value.startsWith("?"))
        return false;
    if (!value.startsWith("/"))
        return false;
    return !filesystemRootPattern.test(value);
}
/**
 * Rewrites root-relative site links and asset paths to include BASE_URL while
 * leaving hashes, queries, external URLs, and likely filesystem paths intact.
 * If the value already begins with the resolved base path, it is returned
 * unchanged.
 */
export function resolveSitePath(value, baseOverride) {
    if (!isBaseRelativePath(value))
        return value;
    const baseUrl = baseOverride ?? readEnvBaseUrl();
    if (baseUrl && baseUrl !== "/") {
        const normalizedBase = baseUrl.endsWith("/") ? baseUrl : `${baseUrl}/`;
        if (value.startsWith(normalizedBase) ||
            value === normalizedBase.slice(0, -1)) {
            return value;
        }
    }
    return url(value, baseOverride);
}
/**
 * Resolves an OG image path to a fully-qualified absolute URL suitable for
 * use in `og:image` and `twitter:image` meta tags.
 *
 * Two corrections are applied that `new URL(ogImage, Astro.url)` does not make:
 *
 * 1. The path is passed through `url()` so that BASE_URL is prepended. This
 *    matters when the site is deployed under a subpath (e.g. PR previews use
 *    `base: "/pr-123/"`). Without this, a root-relative path like
 *    `/og/demos.png` resolves to the wrong location.
 *
 * 2. `Astro.site` (the configured site root) is used as the base rather than
 *    `Astro.url` (the current page URL). `new URL("/og/demos.png", pageUrl)`
 *    ignores any subpath in `pageUrl` because the OG path is root-relative,
 *    so both end up equivalent — but using `Astro.site` makes the intent
 *    explicit and is robust against future path shapes.
 *
 * @param ogImagePath  Root-relative OG image path, e.g. `"/og/home.png"`.
 * @param siteRoot     The site's configured root URL (`Astro.site`), e.g.
 *                     `"https://vizij.ai/"`. Must be an absolute URL string.
 * @param fallback     Path to use when `ogImagePath` is undefined.
 *                     Defaults to `"/social-card.png"`.
 * @returns            Absolute URL string, e.g.
 *                     `"https://vizij.ai/pr-123/og/home.png"`.
 */
export function resolveOgImageUrl(ogImagePath, siteRoot, fallback = "/social-card.png") {
    const resolved = url(ogImagePath ?? fallback);
    return new URL(resolved, siteRoot).href;
}
